// Approved-source registry placeholder.
// Add only sources whose terms permit the intended automated access.
// No network request is made by this node.
const sources = [
  // { name: "Approved source", url: "https://example.co.uk/feed.xml", jurisdiction: "England" }
];
return sources.map(source => ({ json: source }));

// Safe staging gate. An empty registry is an intentional safe state.
// Never interpret an empty response as zero property opportunities.
if (items.length === 0) {
  return [{ json: {
    status: "blocked",
    reason: "No approved UK sources configured",
    opportunitiesFound: 0,
    action: "Configure and review source allowlist before enabling collection"
  }}];
}
return items;

// Evidence validator for staged records.
// This node intentionally does not fetch websites or contact anyone.
return items.map(item => {
  const r = item.json;
  let sourceUrlValid = false;
  try {
    const u = new URL(r.sourceUrl || r.url || "");
    sourceUrlValid =
      (u.protocol === "https:" || u.protocol === "http:") &&
      Boolean(u.hostname) &&
      !/[\\s]/.test(r.sourceUrl || r.url || "");
  } catch {}
  const location = String(r.propertyOrProjectLocation || r.address || "").trim();
  const postcode = String(r.postcode || "").trim().toUpperCase().replace(/\\s+/g, " ");
  return {
    json: {
      ...r,
      sourceUrl: r.sourceUrl || r.url || "",
      sourceUrlValid,
      normalizedPostcode: postcode || undefined,
      evidenceStatus: sourceUrlValid && location ? "review_required" : "quarantine",
      verifiedOwnership: false,
      verifiedDistress: false,
      contactPermissionEstablished: false,
      reviewReason: sourceUrlValid && location
        ? "Evidence is structurally usable but requires human verification."
        : "Missing or invalid source URL or property/project location."
    }
  };
});

// Dry-run review output. No CRM, email, Slack or broker action.
return items.map(item => ({
  json: {
    ...item.json,
    nextAction: "human_review",
    outreachStatus: "not_authorized",
    complianceStatus: "review_required"
  }
}));

return items.map(item => ({
  json: {
    ...item.json,
    nextAction: "quarantine",
    outreachStatus: "not_authorized",
    complianceStatus: "blocked"
  }
}));
